import json, statistics, numpy as np

results = {}
for tag in ['bf16_ds_imp_s010','bf16_ds_imp_s035','bf16_qw_imp_s010','bf16_qw_imp_s035']:
    path = f'/root/autodl-tmp/pacs/profiling_output_{tag}/profiling_results.json'
    d = json.load(open(path))
    ii = d.get('per_problem_ii', d.get('interaction_index', {}))

    # Check structure
    if tag == 'bf16_ds_imp_s010':
        print(f'Keys in per_problem_ii: {list(ii.keys())[:5]}')
        first_k = list(ii.keys())[0]
        print(f'First entry: {ii[first_k]}')

    diffs = []
    for pid, pdata in ii.items():
        if isinstance(pdata, dict):
            hi = pdata.get('high', pdata.get('high_sparsity'))
            lo = pdata.get('low', pdata.get('low_sparsity'))
            if hi is not None and lo is not None:
                diffs.append(lo - hi)
        elif isinstance(pdata, (list, tuple)):
            # maybe [high, mid, low]
            if len(pdata) >= 3:
                diffs.append(pdata[2] - pdata[0])

    med = statistics.median(diffs) if diffs else None
    print(f'{tag}: n={len(diffs)}, median_diff={med}')
"

